-- User-approved name-and-existing-lore classification, reviewed 2026-10-13.
-- This is an auditable project taxonomy, NOT a recovered Tencent race table.
-- See docs/daoist-endgame/monster-family-audit-2026-10-13.tsv for every original
-- row, including excluded noncombat objects, unknowns and recommendations.
-- No damage/range/rank/native-skill/character rows are rewritten.
CREATE TABLE IF NOT EXISTS game_monster_families (
 monster_id INTEGER PRIMARY KEY REFERENCES game_monsters(id) ON DELETE CASCADE,
 family TEXT NOT NULL CHECK (family IN ('unknown','other','undead','demon')),
 lineage TEXT NOT NULL CHECK (lineage <> ''),
 evidence_source TEXT NOT NULL,
 evidence TEXT NOT NULL,
 recommendation TEXT NOT NULL DEFAULT ''
);
-- Separate immutable first-import ledger: replay cannot resurrect a deleted
-- mapping or replace an administrator's earlier/later classification.
CREATE TABLE IF NOT EXISTS game_monster_family_sources (
 monster_id INTEGER PRIMARY KEY,
 expected_name TEXT NOT NULL,
 expected_kind TEXT NOT NULL,
 expected_sprite INTEGER NOT NULL,
 family TEXT NOT NULL CHECK (family IN ('unknown','other','undead','demon')),
 lineage TEXT NOT NULL,
 evidence_source TEXT NOT NULL,
 evidence TEXT NOT NULL,
 recommendation TEXT NOT NULL DEFAULT '',
 source_revision TEXT NOT NULL,
 imported BOOLEAN NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS game_skill_target_families (
 skill_id INTEGER NOT NULL CHECK (skill_id > 0),
 family TEXT NOT NULL CHECK (family IN ('other','undead','demon')),
 PRIMARY KEY (skill_id, family)
);

