 (32913,'天魔*怨灵','普通',362,'undead','天魔*怨灵','game_monsters.name; user-approved name review 2026-10-13','明确尸体、死者灵魂或亡灵主体名；按用户授权名字判定，不声称腾讯原种族表','')
) AS reviewed(monster_id,expected_name,expected_kind,expected_sprite,family,lineage,evidence_source,evidence,recommendation) LOOP
 INSERT INTO game_monster_family_sources
  (monster_id,expected_name,expected_kind,expected_sprite,family,lineage,evidence_source,evidence,recommendation,source_revision)
 VALUES(r.monster_id,r.expected_name,r.expected_kind,r.expected_sprite,r.family,r.lineage,r.evidence_source,r.evidence,r.recommendation,
  'User-approved exact-name and local lore audit 2026-10-13')
 ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN CONTINUE; END IF;
 INSERT INTO game_monster_families(monster_id,family,lineage,evidence_source,evidence,recommendation)
 SELECT r.monster_id,r.family,r.lineage,r.evidence_source,r.evidence,r.recommendation
 FROM game_monsters m WHERE m.id=r.monster_id
   AND m.name=r.expected_name AND m.kind=r.expected_kind AND m.sprite=r.expected_sprite
   AND m.kind IN ('普通','精英','BOSS') AND m.level>0 AND m.hp>0
 ON CONFLICT DO NOTHING;
 IF FOUND THEN
  UPDATE game_monster_family_sources SET imported=true WHERE monster_id=r.monster_id;
 END IF;
END LOOP;
END
$monster_family_import$;

DO $exorcism_target_families$
BEGIN
 INSERT INTO game_skill_mechanism_sources(skill_id,mechanic,source_url,source_revision,imported)
 VALUES(10312,'target_monster_family','game_monsters.name; gamedata.ov_task; gamedata.ov_dialog',
  'User-approved name review 2026-10-13; original Exorcism undead/demon restriction; project classification, not Tencent race metadata',false)
 ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RETURN; END IF;
 IF (SELECT count(*) FROM gamedata.ov_skilldesc WHERE skill_id=10312 AND skill_level BETWEEN 1 AND 5) <> 5 THEN
  RAISE EXCEPTION 'missing original Exorcism anchors';
 END IF;
 -- A pre-existing administrator allow-list is an atomic configuration: keep it
 -- whole, rather than silently broadening it by adding one of our families.
 IF EXISTS(SELECT FROM game_skill_target_families WHERE skill_id=10312) THEN RETURN; END IF;
 INSERT INTO game_skill_target_families(skill_id,family) VALUES(10312,'undead'),(10312,'demon');
 UPDATE game_skill_mechanism_sources SET imported=true
  WHERE skill_id=10312 AND mechanic='target_monster_family';
END
$exorcism_target_families$;
